{
  "scope_issues": [
    "The policy applies to donations from individuals, but does not specify whether direct debit or one-off donations are treated differently; the decision must be evaluated per donation."
  ],
  "statuses": [
    {
      "evidence_quote": "You must be recognised as a charity or CASC for tax purposes.",
      "id": "a1",
      "justification": "The customer scenario states the charity has an HMRC recognition letter, which establishes that the charity is recognised for tax purposes. This supports the proposition that the donor is recognised as a charity or CASC for tax purposes, as the donor is an individual making a donation to the charity.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "",
      "id": "a2",
      "justification": "The customer scenario does not state Robyn Ellis's tax position or how much income tax or capital gains tax she paid in the relevant tax year. No evidence is provided about her tax liability or whether it meets or exceeds the amount of Gift Aid being claimed. Therefore, this is not established.",
      "status": "UNKNOWN"
    },
    {
      "evidence_quote": "",
      "id": "a3",
      "justification": "The customer scenario states that Robyn's tax position and any Gift Aid declaration have not been checked. There is no evidence that she made a Gift Aid declaration. Therefore, the proposition is not supported.",
      "status": "UNKNOWN"
    },
    {
      "evidence_quote": "You cannot claim on donations: made through Payroll Giving",
      "id": "a4",
      "justification": "The donation of £260 was made by Robyn Ellis via direct debit, not through Payroll Giving. The scenario explicitly states the payment was made by direct debit, which is not Payroll Giving. Thus, the donation is not made through Payroll Giving.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: that are a payment for goods or services or made because your charity or CASC bought goods and services",
      "id": "a5",
      "justification": "The scenario states that Robyn paid £260 for an advertising deal in the charity's newsletter and website, which was confirmed after her payment and the advertisement appeared as agreed. This constitutes a payment for goods or services (advertising), and the donation was made in exchange for a service. Therefore, the donation is a payment for goods or services, and this proposition is false.",
      "status": "FALSE"
    },
    {
      "evidence_quote": "You cannot claim on donations: where the donor gets a 'benefit' over a certain limit",
      "id": "a6",
      "justification": "The scenario does not state that Robyn received a benefit over a certain limit. The £260 payment was for advertising, which is a service, not a benefit. There is no evidence that a benefit was received by the donor. Therefore, this proposition is not established.",
      "status": "UNKNOWN"
    },
    {
      "evidence_quote": "You cannot claim on donations: of shares",
      "id": "a7",
      "justification": "The donation is not described as being of shares. The £260 payment was for advertising, not for shares. Therefore, the donation is not of shares.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: from charity cards or of vouchers, for example Charities Aid Foundation (CAF) vouchers",
      "id": "a8",
      "justification": "The donation was made by direct debit and was not from a charity card or voucher. There is no mention of a charity card or voucher. Therefore, the donation is not from such a source.",
      "status": "TRUE"
    }
  ]
}
